public class Solution {
    public int MenorTempoHospital(int n, int[][] roads, int start, int hospital) {
        var adj = new List<(int, int)>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<(int, int)>();
        foreach (var r in roads) {
            adj[r[0]].Add((r[1], r[2]));
            adj[r[1]].Add((r[0], r[2]));
        }
        var dist = new int[n];
        Array.Fill(dist, int.MaxValue);
        dist[start] = 0;
        var heap = new PriorityQueue<int, int>();
        heap.Enqueue(start, 0);
        while (heap.Count > 0) {
            heap.TryDequeue(out int u, out int d);
            if (d > dist[u]) continue;
            if (u == hospital) return d;
            foreach (var (v, w) in adj[u]) {
                int nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    heap.Enqueue(v, nd);
                }
            }
        }
        return -1; // não alcançável (não deve acontecer conforme constraints)
    }
}

