    adj := make([][][2]int, n)
    for _, r := range roads {
        u, v, w := r[0], r[1], r[2]
        adj[u] = append(adj[u], [2]int{v, w})
        adj[v] = append(adj[v], [2]int{u, w})
    }
    dist := make([]int, n)
    for i := range dist {
        dist[i] = int(^uint(0) >> 1) // MaxInt
    }
    dist[start] = 0
    h := &minHeap{{start, 0}}
    heap.Init(h)
    for h.Len() > 0 {
        item := heap.Pop(h).(pair)
        u, d := item.v, item.d
        if d > dist[u] {
            continue
        }
        if u == hospital {
            return d
        }
        for _, e := range adj[u] {
            v, w := e[0], e[1]
            nd := d + w
            if nd < dist[v] {
                dist[v] = nd
                heap.Push(h, pair{v, nd})
            }
        }
    }
    return -1
}

type pair struct{ v, d int }
type minHeap []pair
func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i].d < h[j].d }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(pair)) }
func (h *minHeap) Pop() any          { old := *h; n := len(old); x := old[n-1]; *h = old[:n-1]; return x }

