using System.Collections.Generic;

public class Solution {
    private int minTime = int.MaxValue;
    private HashSet<int> visited = new HashSet<int>();

    public int MenorTempoHospitalNaive(int n, int[][] roads, int start, int hospital) {
        var adj = new List<(int, int)>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<(int, int)>();
        foreach (var r in roads) {
            adj[r[0]].Add((r[1], r[2]));
            adj[r[1]].Add((r[0], r[2]));
        }
        Dfs(start, hospital, 0, adj);
        return minTime == int.MaxValue ? -1 : minTime;
    }

    private void Dfs(int u, int hospital, int currentCost, List<(int, int)>[] adj) {
        visited.Add(u);
        if (u == hospital) {
            minTime = Math.Min(minTime, currentCost);
            visited.Remove(u);
            return;
        }
        foreach (var (v, w) in adj[u]) {
            if (!visited.Contains(v)) {
                Dfs(v, hospital, currentCost + w, adj);
            }
        }
        visited.Remove(u);
    }
}

